<template><div class="page"><div class="page-title"><h2>成本分析</h2><el-button type="primary" :disabled="!canWrite()" @click="targetDialog=true">新增目标</el-button></div><div class="stats"><div class="stat"><div class="label">期间总成本</div><div class="value">{{ summary.total || 0 }}</div></div><div class="stat"><div class="label">单均成本</div><div class="value">{{ summary.costPerOrder || 0 }}</div></div><div class="stat"><div class="label">累计节省</div><div class="value">{{ saving.total || 0 }}</div></div></div><div class="grid-2"><div class="panel"><h3>成本类型</h3><Chart :option="pie" /></div><div class="panel"><h3>成本趋势</h3><Chart :option="trend" /></div></div><div class="panel"><h3>目标与实际</h3><el-table :data="targets" stripe><el-table-column prop="month" label="月份" /><el-table-column prop="costType" label="类型" /><el-table-column prop="targetAmount" label="目标金额" /><el-table-column label="操作"><template #default="{row}"><el-button link type="danger" @click="removeTarget(row)">删除</el-button></template></el-table-column></el-table></div><div class="panel"><h3>成本记录</h3><el-table :data="records" stripe><el-table-column prop="bizDate" label="日期" /><el-table-column prop="orderNo" label="订单" /><el-table-column prop="costType" label="类型" /><el-table-column prop="warehouseCode" label="仓库" /><el-table-column prop="carrierCode" label="承运商" /><el-table-column prop="amount" label="金额" /></el-table></div><el-dialog v-model="targetDialog" title="成本目标"><el-form label-width="90px"><el-form-item label="月份"><el-input v-model="target.month" placeholder="YYYY-MM" /></el-form-item><el-form-item label="类型"><el-input v-model="target.costType" /></el-form-item><el-form-item label="金额"><el-input-number v-model="target.targetAmount" /></el-form-item></el-form><template #footer><el-button @click="targetDialog=false">取消</el-button><el-button type="primary" @click="saveTarget">保存</el-button></template></el-dialog></div></template>
<script setup>
import { computed, reactive, ref } from 'vue'; import { costApi } from '../api'; import { canWrite } from '../auth'; import Chart from '../components/Chart.vue'
const summary=reactive({}),saving=reactive({}),targets=ref([]),records=ref([]),targetDialog=ref(false),target=reactive({month:'',costType:'FREIGHT',targetAmount:0}); const pie=computed(()=>({tooltip:{},series:[{type:'pie',radius:'60%',data:Object.entries(summary.byType||{}).map(([name,value])=>({name,value}))}]})); const trend=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'category',data:Object.keys(summary.trend||{})},yAxis:{type:'value'},series:[{type:'line',areaStyle:{},data:Object.values(summary.trend||{})}]})); async function load(){Object.assign(summary,await costApi.summary());Object.assign(saving,await costApi.saving());targets.value=await costApi.targets();records.value=await costApi.page()};async function saveTarget(){await costApi.saveTarget(target);targetDialog.value=false;load()};async function removeTarget(row){await costApi.deleteTarget(row.id);load()};load()
</script>
